<?php $title='Customizer';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1>CRM Customizer</h1><p>Create configurable fields without changing the database schema.</p></div></div><div class="grid two"><form class="panel form-grid" method="post" action="<?=route('customizer')?>"><?=csrf_field()?><label>Entity<select name="entity_type"><option>client</option><option>business</option><option>project</option><option>service</option><option>invoice</option><option>lead</option></select></label><label>Field key<input name="field_name" required placeholder="preferred_contact"></label><label>Label<input name="field_label" required></label><label>Type<select name="field_type"><option>text</option><option>textarea</option><option>number</option><option>integer</option><option>currency</option><option>email</option><option>phone</option><option>date</option><option>datetime</option><option>dropdown</option><option>multiselect</option><option>checkbox</option><option>url</option></select></label><label>Dropdown options<input name="options" placeholder="Email,Phone,SMS"></label><label>Sort order<input name="sort_order" type="number" value="0"></label><label><input type="checkbox" name="is_required" value="1"> Required</label><div class="wide"><button class="primary">Add field</button></div></form><div class="panel"><h2>Fields</h2><table><tr><th>Entity</th><th>Field</th><th>Type</th><th>Required</th></tr><?php foreach($fields as $f):?><tr><td><?=e($f['entity_type'])?></td><td><?=e($f['field_label'])?></td><td><?=e($f['field_type'])?></td><td><?=!empty($f['is_required'])?'Yes':'No'?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../layouts/footer.php';?>
